    "s1-equations-a/q11": ["錯解辨析","",[["小晴把 5−3(x＋5) 展開為 5−3x＋15。指出她的符號錯誤，並寫出正確簡式。","−3 要乘括號內兩項，常數項應為 −15",null,"正確簡式為 −3x−10"],["小晴把 7−4(x＋6) 展開為 7−4x＋24。指出她的符號錯誤，並寫出正確簡式。","−4 要乘括號內兩項，常數項應為 −24",null,"正確簡式為 −4x−17"],["小晴把 9−2(x＋7) 展開為 9−2x＋14。指出她的符號錯誤，並寫出正確簡式。","−2 要乘括號內兩項，常數項應為 −14",null,"正確簡式為 −2x−5"],["小晴把 11−3(x＋8) 展開為 11−3x＋24。指出她的符號錯誤，並寫出正確簡式。","−3 要乘括號內兩項，常數項應為 −24",null,"正確簡式為 −3x−13"],["小晴把 13−4(x＋9) 展開為 13−4x＋36。指出她的符號錯誤，並寫出正確簡式。","−4 要乘括號內兩項，常數項應為 −36",null,"正確簡式為 −4x−23"],["小晴把 15−2(x＋10) 展開為 15−2x＋20。指出她的符號錯誤，並寫出正確簡式。","−2 要乘括號內兩項，常數項應為 −20",null,"正確簡式為 −2x−5"],["小晴把 17−3(x＋11) 展開為 17−3x＋33。指出她的符號錯誤，並寫出正確簡式。","−3 要乘括號內兩項，常數項應為 −33",null,"正確簡式為 −3x−16"],["小晴把 19−4(x＋12) 展開為 19−4x＋48。指出她的符號錯誤，並寫出正確簡式。","−4 要乘括號內兩項，常數項應為 −48",null,"正確簡式為 −4x−29"],["小晴把 21−2(x＋13) 展開為 21−2x＋26。指出她的符號錯誤，並寫出正確簡式。","−2 要乘括號內兩項，常數項應為 −26",null,"正確簡式為 −2x−5"],["小晴把 23−3(x＋14) 展開為 23−3x＋42。指出她的符號錯誤，並寫出正確簡式。","−3 要乘括號內兩項，常數項應為 −42",null,"正確簡式為 −3x−19"]],"進階"],
    "s1-equations-a/q12": ["解的情況","",[["若 3(3x＋4)=9x＋k 對所有 x 都成立，求 k。","把左邊展開為 9x＋12，比較常數項",12,"k=12"],["若 4(4x＋5)=16x＋k 對所有 x 都成立，求 k。","把左邊展開為 16x＋20，比較常數項",20,"k=20"],["若 5(5x＋6)=25x＋k 對所有 x 都成立，求 k。","把左邊展開為 25x＋30，比較常數項",30,"k=30"],["若 6(2x＋7)=12x＋k 對所有 x 都成立，求 k。","把左邊展開為 12x＋42，比較常數項",42,"k=42"],["若 7(3x＋8)=21x＋k 對所有 x 都成立，求 k。","把左邊展開為 21x＋56，比較常數項",56,"k=56"],["若 8(4x＋9)=32x＋k 對所有 x 都成立，求 k。","把左邊展開為 32x＋72，比較常數項",72,"k=72"],["若 9(5x＋10)=45x＋k 對所有 x 都成立，求 k。","把左邊展開為 45x＋90，比較常數項",90,"k=90"],["若 10(2x＋11)=20x＋k 對所有 x 都成立，求 k。","把左邊展開為 20x＋110，比較常數項",110,"k=110"],["若 11(3x＋12)=33x＋k 對所有 x 都成立，求 k。","把左邊展開為 33x＋132，比較常數項",132,"k=132"],["若 12(4x＋13)=48x＋k 對所有 x 都成立，求 k。","把左邊展開為 48x＋156，比較常數項",156,"k=156"]],"進階"],
    "s1-equations-b/q1": ["逆運算","",[["某數加上 11 後得到 -7。求原數。","設原數為 x，列出 x＋11=-7 或等值算式",-18,"x=-7−11=-18"],["某數加上 13 後得到 -8。求原數。","設原數為 x，列出 x＋13=-8 或等值算式",-21,"x=-8−13=-21"],["某數加上 15 後得到 -9。求原數。","設原數為 x，列出 x＋15=-9 或等值算式",-24,"x=-9−15=-24"],["某數加上 17 後得到 -10。求原數。","設原數為 x，列出 x＋17=-10 或等值算式",-27,"x=-10−17=-27"],["某數加上 19 後得到 -11。求原數。","設原數為 x，列出 x＋19=-11 或等值算式",-30,"x=-11−19=-30"],["某數加上 21 後得到 -12。求原數。","設原數為 x，列出 x＋21=-12 或等值算式",-33,"x=-12−21=-33"],["某數加上 23 後得到 -13。求原數。","設原數為 x，列出 x＋23=-13 或等值算式",-36,"x=-13−23=-36"],["某數加上 25 後得到 -14。求原數。","設原數為 x，列出 x＋25=-14 或等值算式",-39,"x=-14−25=-39"],["某數加上 27 後得到 -15。求原數。","設原數為 x，列出 x＋27=-15 或等值算式",-42,"x=-15−27=-42"],["某數加上 29 後得到 -16。求原數。","設原數為 x，列出 x＋29=-16 或等值算式",-45,"x=-16−29=-45"]],"基礎"],
    "s1-equations-b/q2": ["合併同類項","",[["解方程 5−3v＋6v=-4。","合併同類項，得 3v＋5=-4",-3,"3v=-9，v=-3"],["解方程 6−4v＋7v=-6。","合併同類項，得 3v＋6=-6",-4,"3v=-12，v=-4"],["解方程 7−2v＋8v=-23。","合併同類項，得 6v＋7=-23",-5,"6v=-30，v=-5"],["解方程 8−3v＋9v=-28。","合併同類項，得 6v＋8=-28",-6,"6v=-36，v=-6"],["解方程 9−4v＋10v=-33。","合併同類項，得 6v＋9=-33",-7,"6v=-42，v=-7"],["解方程 10−2v＋11v=-62。","合併同類項，得 9v＋10=-62",-8,"9v=-72，v=-8"],["解方程 11−3v＋12v=-70。","合併同類項，得 9v＋11=-70",-9,"9v=-81，v=-9"],["解方程 12−4v＋13v=-78。","合併同類項，得 9v＋12=-78",-10,"9v=-90，v=-10"],["解方程 13−2v＋14v=-119。","合併同類項，得 12v＋13=-119",-11,"12v=-132，v=-11"],["解方程 14−3v＋15v=-130。","合併同類項，得 12v＋14=-130",-12,"12v=-144，v=-12"]],"基礎"],
    "s1-equations-b/q3": ["移項","",[["解方程 5−3a=-5−7a。","把未知數項移到同一邊，得 4a=-10",-2.5,"a=-2.5"],["解方程 6−4a=27−10a。","把未知數項移到同一邊，得 6a=21",3.5,"a=3.5"],["解方程 7−5a=-2−7a。","把未知數項移到同一邊，得 2a=-9",-4.5,"a=-4.5"],["解方程 8−6a=30−10a。","把未知數項移到同一邊，得 4a=22",5.5,"a=5.5"],["解方程 9−7a=-30−13a。","把未知數項移到同一邊，得 6a=-39",-6.5,"a=-6.5"],["解方程 10−8a=25−10a。","把未知數項移到同一邊，得 2a=15",7.5,"a=7.5"],["解方程 11−9a=-23−13a。","把未知數項移到同一邊，得 4a=-34",-8.5,"a=-8.5"],["解方程 12−10a=69−16a。","把未知數項移到同一邊，得 6a=57",9.5,"a=9.5"],["解方程 13−11a=-8−13a。","把未知數項移到同一邊，得 2a=-21",-10.5,"a=-10.5"],["解方程 14−12a=60−16a。","把未知數項移到同一邊，得 4a=46",11.5,"a=11.5"]],"基礎"],
